      for  c  in  s:
            flag  =  c.islower()
      return  flag

def  any_lowercase4(s):
      flag  =  False
      for  c  in  s:
            flag  =  flag  or  c.islower()
      return  flag

def  any_lowercase5(s):
      for  c  in  s:
            if  not  c.islower():
                   return  False
      return  True
